<!-- This file is generated by AI. -->
<!--
  诊断列表: 弹窗与底部托盘**共用同一份实现**。

  值得记住的一条语义 (来自 `diagnostics/model.ts`): 诊断是**按项目整体推送**的, 所以
  `store.diagnostics` 的键集合就是"已经收到结果的场景" —— 据此才能区分「还没结果」与
  「确实没问题」。列表因此在空的时候也要说清楚是哪种情况 (文案来自 `describeDiagnostics`)。

  入口在状态栏, 渲染在编辑页, 两者不在同一棵子树里, 所以"是否打开"放在 store 而不是局部状态。

  结构上有一条硬约束: 筛选条与列表必须是外壳的**直接子项**, 中间不能再包一层容器 ——
  `.dialog-compact .dialog-body > :where(:not(.dialog-scroll)) { flex: none }` 会把包层
  压成内容高度, 而 `.dialog-scroll` (列表) 只有在直接子项时才拿得到 `flex: 1`, 包一层
  就等于同时丢掉滚动条与裁剪 (内容被 `overflow: hidden` 吃掉)。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { onDestroy } from 'svelte';

  import {
    buildDiagnosticsExport,
    codeStats,
    collectProjectDiagnostics,
    countBySeverity,
    countEntries,
    defaultFilter,
    describeDiagnostics,
    filterDiagnosticFiles,
    severityStats,
    splitScenePath,
    SEVERITY_LABELS,
    SEVERITY_ORDER,
    type DiagnosticEntry,
    type DiagnosticFile,
    type DiagnosticFilter,
    type Severity,
  } from '../diagnostics/model';
  import { openFile } from '../project';
  import { actions, appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Checkbox from './Checkbox.svelte';
  import Icon from './Icon.svelte';
  import Input from './Input.svelte';
  import type { IconName } from './icons';

  let {
    /** 打开形式: 弹窗 / 底部托盘 (来自设置) */
    variant,
    onClose,
  }: {
    variant: 'modal' | 'dock';
    onClose: () => void;
  } = $props();

  const collected = $derived(collectProjectDiagnostics(appStore.diagnostics, appStore.projectPath));

  /*
   * `userFilter === null` 表示"还在用默认条件"。
   *
   * 默认条件依赖数据 (项目里出现了哪些级别), 而数据是异步到的: 把它固化成初始值的话,
   * 挂载时还没收到结果、默认筛选算出来是空, 后到的错误级就永远进不了列表。`null` 还让
   * "清除筛选"有了明确的目标 —— 回到当下的默认, 而不是回到挂载那一刻的快照。
   */
  let userFilter = $state<DiagnosticFilter | null>(null);

  const fallback = $derived(defaultFilter(collected.files));
  const filter = $derived(userFilter ?? fallback);

  const codes = $derived(codeStats(collected.files));
  /** 筛选条上的级别开关: 只列出现过的级别, 数字是全项目条数 */
  const levels = $derived(severityStats(collected.files));
  /** `codes === null` 表示"尚未限定", 等同于全选 */
  const selectedCodes = $derived(filter.codes ?? codes.map((stat) => stat.code));

  const visibleFiles = $derived(filterDiagnosticFiles(collected.files, filter));
  const visibleCount = $derived(countEntries(visibleFiles));
  const totalCount = $derived(countEntries(collected.files));
  const hiddenCount = $derived(totalCount - visibleCount);

  /*
   * 列表**分批渲染**。
   *
   * 一批诊断可以有几百个文件、每个文件几十条 —— 一次性建出全部 DOM 是几千个节点 (每条还带
   * 一个内联 SVG 图标), 滚动就会掉帧。这与 `ui/FileTree.svelte` 的"已渲染行数"是同一个做法,
   * 不引入虚拟滚动。
   *
   * 首次给 80 个分组 (常见项目一屏就够), 滚到接近底部再按 80 递增 —— 只增加, 不删除,
   * 因此滚动位置不会跳。筛选条件变化时由下面那个 `$effect` 复位到 80。
   */
  const DIAG_CHUNK = 80;
  let renderedGroups = $state(DIAG_CHUNK);
  const shownFiles = $derived(visibleFiles.slice(0, renderedGroups));

  /*
   * 条件变了就回到第一批。
   *
   * 依赖取"结果的数量 + 分组签名"而不是整个数组: 数组每次筛选都会新建, 直接依赖它会在
   * 每次诊断推送时复位 (那样滚动时反而会闪)。这里只在**可见集合真的换了**时复位。
   */
  let lastSignature = '';
  $effect(() => {
    const signature = `${visibleFiles.length}:${visibleFiles[0]?.path ?? ''}:${filter.query}:${[...filter.severities].join(',')}`;
    if (signature === lastSignature) return;
    lastSignature = signature;
    renderedGroups = DIAG_CHUNK;
  });

  /** 滚到接近底部就再放一批。 */
  function extendOnScroll(event: Event): void {
    const el = event.currentTarget as HTMLElement;
    if (el.scrollTop + el.clientHeight < el.scrollHeight - 240) return;
    if (renderedGroups >= visibleFiles.length) return;
    renderedGroups += DIAG_CHUNK;
  }

  /*
   * 标题下那行小字, 外加"列表为空时该说什么"。
   *
   * `emptyText` 为 null 表示"数据里确实有问题, 空是筛出来的", 那时由列表自己给"清除筛选"
   * (这句话与那个按钮都属于列表的行为, 见下面的空态)。
   */
  const described = $derived(
    describeDiagnostics({
      scenes: collected.scenes,
      total: totalCount,
      visible: visibleCount,
      hidden: hiddenCount,
      lspStatus: appStore.lspStatus,
    })
  );

  let codesOpen = $state(false);
  let codesRoot: HTMLDivElement | undefined = $state();
  /** 已折叠的组 (存路径而不是下标: 筛选一变, 下标就换人了) */
  let collapsed = $state<string[]>([]);
  /** 刚刚复制成功的目标: 'result' 或某个文件路径 */
  let copied = $state<string | null>(null);

  const COPIED_MS = 1600;
  let copyTimer: ReturnType<typeof setTimeout> | null = null;
  onDestroy(() => {
    if (copyTimer !== null) clearTimeout(copyTimer);
  });

  const SEVERITY_ICON: Record<Severity, IconName> = {
    1: 'ErrorCircle',
    2: 'Warning',
    3: 'Info',
    4: 'Lightbulb',
  };

  /** 组头角标的类名后缀 (与文件树的角标同一套颜色: `.diag-badge.diag-error` 等) */
  const BADGE_NAMES: Record<Severity, string> = { 1: 'error', 2: 'warn', 3: 'info', 4: 'hint' };

  // ---- 筛选 ----

  function patch(next: Partial<DiagnosticFilter>): void {
    userFilter = { ...filter, ...next };
  }

  function toggleSeverity(severity: Severity): void {
    const has = filter.severities.includes(severity);
    // 允许一个级别都不选 (那就是"暂时什么都别看"), 因此不做"至少留一个"的兜底
    patch({
      severities: has
        ? filter.severities.filter((item) => item !== severity)
        : [...filter.severities, severity].sort((a, b) => a - b),
    });
  }

  function toggleCode(code: string): void {
    /*
     * 用数组运算而不是 `Set` 去重: 一是这里只处理几十个诊断码, 二是 Svelte 的
     * `prefer-svelte-reactivity` 规则会 (正确地) 把组件里的 `Set` 当成可疑的响应式状态。
     */
    const current = selectedCodes;
    patch({ codes: current.includes(code) ? current.filter((item) => item !== code) : [...current, code] });
  }

  function setAllCodes(on: boolean): void {
    patch({ codes: on ? codes.map((stat) => stat.code) : [] });
  }

  function setQuery(event: Event): void {
    patch({ query: (event.currentTarget as HTMLInputElement).value });
  }

  // ---- 复制 ----

  function copyText(text: string, key: string): void {
    void navigator.clipboard
      .writeText(text)
      .then(() => {
        copied = key;
        if (copyTimer !== null) clearTimeout(copyTimer);
        copyTimer = setTimeout(() => (copied = null), COPIED_MS);
      })
      .catch((error) => console.error('复制诊断失败', error));
  }

  /** 复制整个筛选结果 (外壳上的"复制结果") */
  function copyResult(): void {
    copyText(buildExport({ kind: 'project' }, visibleFiles), 'result');
  }

  /** 复制单个文件的诊断 (组头上的复制按钮) */
  function copyFile(file: DiagnosticFile): void {
    copyText(buildExport({ kind: 'file', path: file.path }, [file]), file.path);
  }

  function buildExport(scope: { kind: 'project' } | { kind: 'file'; path: string }, files: DiagnosticFile[]): string {
    return buildDiagnosticsExport({
      projectName: appStore.projectName ?? '未命名项目',
      scope,
      files,
    });
  }

  // ---- 跳转 ----

  function openEntry(entry: DiagnosticEntry): void {
    /*
     * 先记请求再读盘: 读盘是异步的, 编辑器挂载时这条请求已经在了。
     * 必须走 `openFile` 而不是"只开选项卡": 前者才会把文件读进 `documents`, 否则编辑区
     * 会一直停在"正在读取场景…"上 (store 里只有选项卡, 没有内容可渲染)。
     *
     * **结束位置直接由条目给出** (`DiagnosticEntry` 本来就有 `endLine`/`endColumn`):
     * 编辑器据此选中该诊断画波浪线的那一段, 而不是只放一个光标 —— 点一条诊断的人想看的
     * 正是"被标出来的是哪几个字"。
     */
    actions.requestReveal(entry.path, entry.line, entry.column, {
      line: entry.endLine,
      column: entry.endColumn,
    });
    void openFile(entry.path).catch((error) => console.error('打开诊断所在场景失败', error));
    // 弹窗盖住了编辑区, 不关就看不到刚跳到的代码; 托盘与代码同时可见, 一直开着
    if (variant === 'modal') onClose();
  }

  function toggleCollapsed(path: string): void {
    collapsed = collapsed.includes(path) ? collapsed.filter((item) => item !== path) : [...collapsed, path];
  }

  /*
   * 点外部 / Esc 收起码浮层。
   *
   * 用 window 的**捕获阶段**: 浮层在弹窗内部, 只有先于弹窗拿到事件, 才截得住那次 Esc
   * (`stopPropagation` 之后弹窗的监听收不到, 于是"关浮层"与"关弹窗"不会一起发生)。
   */
  $effect(() => {
    if (!codesOpen) return;
    const onPointerDown = (event: PointerEvent) => {
      if (!codesRoot?.contains(event.target as Node)) codesOpen = false;
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.stopPropagation();
      codesOpen = false;
    };
    window.addEventListener('pointerdown', onPointerDown, true);
    window.addEventListener('keydown', onKeyDown, true);
    return () => {
      window.removeEventListener('pointerdown', onPointerDown, true);
      window.removeEventListener('keydown', onKeyDown, true);
    };
  });

  /*
   * 托盘形态的 Esc 收起。上面盖着对话框时不动 —— 那次 Esc 属于那个对话框。
   *
   * 判据是**文档里还有没有 `.modal-surface`**, 与 `AppDialog` 自己的一致: 不能靠"打开顺序栈",
   * 应用级确认框与调用它的对话框在 DOM 里是兄弟节点, 只看自己的子树会漏判, 一次 Esc 会把整叠
   * 一起关掉。
   */
  $effect(() => {
    if (variant !== 'dock') return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.isComposing) return;
      if (document.querySelector('.modal-surface')) return;
      onClose();
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  });
</script>

<!--
  筛选条 + 列表。刻意不包容器: 两者都是外壳的直接子项, 列表才能以内滚条撑满剩余高度。
-->
{#snippet body()}
  <div class="diag-bar">
    {#each levels as { severity, count } (severity)}
      {@const on = filter.severities.includes(severity)}
      <button
        type="button"
        class="diag-severity"
        class:on
        aria-pressed={on}
        title={on ? `不再显示${SEVERITY_LABELS[severity]}` : `显示${SEVERITY_LABELS[severity]}`}
        onclick={() => toggleSeverity(severity)}
      >
        <span class="diag-severity-dot diag-sev-{severity}"></span>
        {SEVERITY_LABELS[severity]}
        <span class="diag-severity-count">{count}</span>
      </button>
    {/each}

    {#if codes.length > 1}
      <span class="diag-bar-divider"></span>

      <div class="diag-codes" bind:this={codesRoot}>
        <button
          type="button"
          class="diag-codes-trigger"
          class:open={codesOpen}
          aria-expanded={codesOpen}
          onclick={() => (codesOpen = !codesOpen)}
        >
          诊断码
          <span class="diag-codes-trigger-count">{selectedCodes.length}/{codes.length}</span>
          <Icon name="ChevronDown" />
        </button>

        {#if codesOpen}
          <div class="diag-codes-panel" role="listbox" aria-label="诊断码">
            <div class="diag-codes-panel-head">
              <span>诊断码</span>
              <button type="button" class="diag-link" onclick={() => setAllCodes(true)}>全选</button>
              <button type="button" class="diag-link" onclick={() => setAllCodes(false)}>清空</button>
            </div>
            <div class="diag-codes-panel-body">
              {#each codes as stat (stat.code)}
                <div class="diag-code-item">
                  <Checkbox checked={selectedCodes.includes(stat.code)} onchange={() => toggleCode(stat.code)} />
                  <span class="diag-code-name diag-sev-{stat.severity}">{stat.code}</span>
                  <span class="diag-code-count">{stat.count}</span>
                </div>
              {/each}
            </div>
          </div>
        {/if}
      </div>
    {/if}

    <Input className="diag-search" placeholder="筛选消息或文件…" value={filter.query} oninput={setQuery} />

    <!--
      这里**没有**"清除筛选"按钮: 筛选条件 (级别胶囊 + 搜索框 + 诊断码) 都摆在这一行上,
      再放一个复位按钮既重复又占地方。条件偏离默认时, 下面那行描述文字会写明"X 条已隐藏",
      想回到默认逐项点回去即可。
    -->
  </div>

  {#if visibleFiles.length === 0}
    <div class="diag-list dialog-scroll">
      <div class="diag-empty">
        <!--
          主句由 `describeDiagnostics` 给出 ("还没有收到诊断结果" / "没有发现问题")。
          它返回 null 说明数据里确实有问题, 只是被筛选挡光了。
        -->
        <p>{described.emptyText ?? '没有符合当前筛选的诊断'}</p>
      </div>
    </div>
  {:else}
    <!-- 分批渲染: 见脚本里 `renderedGroups` 的说明 -->
    <div class="diag-list dialog-scroll" onscroll={extendOnScroll}>
      {#each shownFiles as file (file.path)}
        {@const isCollapsed = collapsed.includes(file.path)}
        <!-- 角标与行同源: 数的是这一组**当前列出的**条目, 四个级别一个不落 -->
        {@const counts = countBySeverity(file.entries)}
        {@const parts = splitScenePath(file.scene)}
        <div class="diag-group">
          <div
            class="diag-group-head"
            role="button"
            tabindex="0"
            aria-expanded={!isCollapsed}
            onclick={() => toggleCollapsed(file.path)}
            onkeydown={(event) => {
              if (event.key !== 'Enter' && event.key !== ' ') return;
              event.preventDefault();
              toggleCollapsed(file.path);
            }}
          >
            <Icon name={isCollapsed ? 'ChevronRight' : 'ChevronDown'} />
            <span class="diag-group-path">
              <span class="diag-group-dir">{parts.dir}</span>{parts.name}
            </span>
            <span class="diag-group-counts">
              {#each SEVERITY_ORDER as severity (severity)}
                {#if counts[severity] > 0}
                  <span class="diag-badge diag-{BADGE_NAMES[severity]}">{counts[severity]}</span>
                {/if}
              {/each}
            </span>
            <button
              type="button"
              class="diag-group-copy"
              title="复制此文件的诊断 (JSON)"
              aria-label="复制此文件的诊断"
              onclick={(event) => {
                // 组头自己也响应点击 (折叠), 复制不该顺手把组收起来
                event.stopPropagation();
                copyFile(file);
              }}
            >
              <Icon name={copied === file.path ? 'Checkmark' : 'Copy'} />
            </button>
          </div>

          {#if !isCollapsed}
            {#each file.entries as entry (`${entry.line}:${entry.column}:${entry.code}`)}
              <button type="button" class="diag-row" title={entry.message} onclick={() => openEntry(entry)}>
                <span class="diag-pos">{entry.line}:{entry.column}</span>
                <span class="diag-row-icon diag-sev-{entry.severity}">
                  <Icon name={SEVERITY_ICON[entry.severity]} />
                </span>
                <span class="diag-msg">{entry.message}</span>
                <span class="diag-code">{entry.code}</span>
              </button>
            {/each}
          {/if}
        </div>
      {/each}
    </div>
  {/if}
{/snippet}

{#if variant === 'modal'}
  <AppDialog title="诊断" description={described.description} size="large" height={640} compact flush {onClose}>
    {@render body()}

    {#snippet footer()}
      <Button appearance="subtle" onclick={onClose}>关闭</Button>
      <Button appearance="primary" disabled={visibleCount === 0} onclick={copyResult}>
        {copied === 'result' ? '已复制' : '复制结果'}
      </Button>
    {/snippet}
  </AppDialog>
{:else}
  <section class="diag-dock" aria-label="诊断">
    <div class="diag-dock-head">
      <span class="diag-dock-title">诊断</span>
      <span class="diag-dock-description">{described.description}</span>
      <span class="diag-dock-spacer"></span>
      <Button icon="Copy" disabled={visibleCount === 0} onclick={copyResult}>
        {copied === 'result' ? '已复制' : '复制结果'}
      </Button>
      <Button appearance="subtle" icon="Dismiss" title="收起诊断" onclick={onClose} />
    </div>
    {@render body()}
  </section>
{/if}
